import sys, os, re
sys.path.insert(0, os.path.dirname(__file__))
from driver import *
DEMO = "Demo-pass-2030!"
env = open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), ".env")).read()
ADMIN_EMAIL = re.search(r"^ADMIN_EMAIL=(.*)$", env, re.M).group(1).strip('"')
ADMIN_PW = re.search(r"^ADMIN_PASSWORD=(.*)$", env, re.M).group(1).strip('"')
for jar, email, pw in [("/tmp/j_own", "demo.owner@example.com", DEMO), ("/tmp/j_co", "demo.company@example.com", DEMO), ("/tmp/j_cust", "demo.customer@example.com", DEMO), ("/tmp/j_cust2", "demo.customer2@example.com", DEMO), ("/tmp/j_adm", ADMIN_EMAIL, ADMIN_PW)]:
    login(jar, email, pw)
A, C = "/tmp/j_adm", "/tmp/j_co"
co_id = sql("select id from users where email='demo.company@example.com'")

print("== COMPANY: bulk offers")
check("an owner cannot open the offers page", status("/tmp/j_own", "/provider/quotes").startswith("307") and "forbidden" in status("/tmp/j_own", "/provider/quotes"))
page = get(C, "/provider/quotes")
check("the open offer lists exact vehicles, version and total", "Version 1" in text(page) and "Accept version 1" in text(page) and re.search(r"4 of 4 vehicles", text(page)) is not None, text(page)[:200])
quote = sql(f"select id from quote_requests where user_id='{co_id}' and status='QUOTED' limit 1")
acc = find_form(page, has=["id", "revision"], contains="Accept version")
r = submit(C, "/provider/quotes", acc, {"revision": "99"})
check("accepting a version the company did not see is refused and books nothing", "notice=STALE_REVISION" in r and sql(f"select count(*) from bookings where quote_id='{quote}'") == "0", r)
# make the open offer stale: somebody else books one of its vehicles
item = sql(f"select vehicle_id from quote_items where quote_id='{quote}' order by vehicle_id limit 1")
cust = sql("select id from users where email='demo.customer@example.com'")
sql(f"insert into bookings(id,vehicle_id,customer_id,user_id,start_at,end_at,status,total_price,commission_bps,commission_amount) select 'stale_b1', '{item}', c.id, '{cust}', q.start_date + interval '12 hours', q.start_date + interval '14 hours', 'PENDING', 1000, 0, 0 from quote_requests q, customers c where q.id='{quote}' and c.email='demo.customer@example.com' limit 1")
r = submit(C, "/provider/quotes", acc, {"revision": "1"})
check("when a listed vehicle was taken, nothing is confirmed and the offer is recalculated with a new version", "notice=OFFER_CHANGED" in r and sql(f"select count(*) from bookings where quote_id='{quote}'") == "0" and sql(f"select revision from quote_requests where id='{quote}'") == "2", r)
page = get(C, "/provider/quotes?notice=OFFER_CHANGED")
check("the page explains it and shows version 2 with an explicit new acceptance button", "Nothing was booked" in text(page) and "Accept version 2" in text(page))
check("the old version cannot be accepted any more", "notice=STALE_REVISION" in submit(C, "/provider/quotes", acc, {"revision": "1"}))
acc2 = find_form(get(C, "/provider/quotes"), has=["id", "revision"], contains="Accept version 2")
r = submit(C, "/provider/quotes", acc2)
n_items = sql(f"select count(*) from quote_items where quote_id='{quote}'")
check("the explicit acceptance of the new version books exactly the listed vehicles", "notice=accepted" in r and sql(f"select count(*) from bookings where quote_id='{quote}'") == n_items and sql(f"select status from quote_requests where id='{quote}'") == "ACCEPTED", r)
check("every booking has its snapshot and a history row", sql(f"select count(*) from bookings b where quote_id='{quote}' and commission_bps is not null and exists(select 1 from booking_status_history h where h.booking_id=b.id and h.to_status='CONFIRMED')") == n_items)
page = get(C, "/provider/quotes")
f = find_form(page, has=["vehicleType", "quantity"])
r = submit(C, "/provider/quotes", f, {"quantity": "1", "startDate": "2031-05-05", "endDate": "2031-05-06", "contactPhone": "0700000000", "purpose": "One vehicle only"})
check("a request for a single vehicle is refused", "notice=invalid" in r, r)
r = submit(C, "/provider/quotes", f, {"quantity": "2", "startDate": "2020-05-05", "endDate": "2020-05-06", "contactPhone": "0700000000", "purpose": "Past dates"})
check("a request that starts in the past is refused", "notice=invalid" in r, r)
r = submit(C, "/provider/quotes", f, {"quantity": "2", "startDate": "2031-05-05", "endDate": "2031-05-06", "contactPhone": "0700000000", "purpose": "Two vehicles in May"})
check("a valid request produces an offer", "notice=requested" in r and sql(f"select status||'|'||revision from quote_requests where user_id='{co_id}' and purpose='Two vehicles in May'") == "QUOTED|1", r)

print("== ADMIN: bookings")
lst = text(get(A, "/admin/bookings?flag=delayed"))
check("the delayed-handover filter finds the late booking", "HANDOVER_DELAYED" in lst and "Polaris Sportsman 570" in lst, lst[:200])
bk = sql("select b.id from bookings b join vehicles v on v.id=b.vehicle_id where v.plate='BV-05-ATV' and b.status='CONFIRMED' and b.start_at < now() limit 1")
page = get(A, f"/admin/bookings/{bk}")
check("the detail page shows the HANDOVER_DELAYED warning, snapshot and history", "HANDOVER_DELAYED" in text(page) and "Commission snapshot" in text(page) and "History" in text(page))
act = find_form(page, has=["bookingId", "reason"])
r = submit(A, f"/admin/bookings/{bk}", act, {"reason": ""}, button=("to", "ACTIVE"))
check("a handover more than 1 hour late needs a reason", "error=REASON_REQUIRED" in r and sql(f"select status from bookings where id='{bk}'") == "CONFIRMED", r)
r = submit(A, f"/admin/bookings/{bk}", act, {"reason": "Customer arrived late (UI test)"}, button=("to", "ACTIVE"))
check("with a reason the handover is recorded", sql(f"select status from bookings where id='{bk}'") == "ACTIVE" and sql(f"select note from booking_status_history where booking_id='{bk}' and to_status='ACTIVE'") == "Customer arrived late (UI test)", r)
vlist = text(get(A, "/admin/vehicles?q=Polaris%20Sportsman"))
check("the vehicle now shows as rented (derived from the active booking)", "Rented now" in vlist, vlist[:200])
check("the stored status is untouched", sql("select status from vehicles where plate='BV-05-ATV'") == "AVAILABLE")
vid = sql("select id from vehicles where plate='BV-05-ATV'")
vpage = get(A, f"/admin/vehicles/{vid}")
chg = find_form(vpage, has=["vehicleId", "to"])
r = submit(A, f"/admin/vehicles/{vid}", chg, {"to": "IN_SERVICE"})
check("a vehicle that is out with a customer cannot be put in service", "error=VEHICLE_RENTED" in r and sql(f"select status from vehicles where id='{vid}'") == "AVAILABLE", r)
check("the refusal is explained on the page", "currently out with a customer" in text(get(A, f"/admin/vehicles/{vid}?error=VEHICLE_RENTED")))
# complete the overdue Honda (ACTIVE, ended 2 days ago, no payments)
hb = sql("select b.id from bookings b join vehicles v on v.id=b.vehicle_id where v.plate='GL-03-MOT' and b.status='ACTIVE' limit 1")
page = get(A, f"/admin/bookings/{hb}")
check("an overdue return is flagged", "Return overdue" in text(page))
act = find_form(page, has=["bookingId", "reason"])
r = submit(A, f"/admin/bookings/{hb}", act, {}, button=("to", "COMPLETED"))
check("completing with an unpaid balance works and warns", sql(f"select status from bookings where id='{hb}'") == "COMPLETED" and "unpaid=" in r, r)
check("nothing was marked as paid automatically", sql(f"select count(*) from payments where booking_id='{hb}'") == "0")
page = get(A, f"/admin/bookings/{hb}")
check("the warning is shown on the page", "unpaid" in text(get(A, f"/admin/bookings/{hb}?ok=COMPLETED&unpaid=22500")).lower())
pay = find_form(page, has=["bookingId", "amount"])
r = submit(A, f"/admin/bookings/{hb}", pay, {"amount": "50", "currency": "EUR", "method": "CARD_POS"})
check("a payment in EUR is converted at the configured rate and stored with it", sql(f"select amount||'|'||currency||'|'||paid_amount||'|'||exchange_rate from payments where booking_id='{hb}'") == "25000|EUR|5000|5.0000", r)
r = submit(A, f"/admin/bookings/{hb}", pay, {"amount": "-5", "currency": "RON", "method": "CASH"})
check("a negative payment is refused", "error=PAYMENT_INVALID" in r, r)
up = sql("select b.id from bookings b join vehicles v on v.id=b.vehicle_id where v.plate='BV-05-ATV' and b.status='CONFIRMED' and b.start_at > now() limit 1")
page = get(A, f"/admin/bookings/{up}")
act = find_form(page, has=["bookingId", "reason"])
r = submit(A, f"/admin/bookings/{up}", act, {"reason": ""}, button=("to", "CANCELLED"))
check("an administrator cannot cancel without a reason", "error=REASON_REQUIRED" in r and sql(f"select status from bookings where id='{up}'") == "CONFIRMED", r)
r = submit(A, f"/admin/bookings/{up}", act, {"reason": "Vehicle damaged (UI test)"}, button=("to", "CANCELLED"))
check("with a reason the cancellation works and is in the history", sql(f"select status from bookings where id='{up}'") == "CANCELLED" and sql(f"select note from booking_status_history where booking_id='{up}' and to_status='CANCELLED'") == "Vehicle damaged (UI test)", r)
check("a cancelled booking offers no more actions", find_form(get(A, f"/admin/bookings/{up}"), has=["bookingId", "reason"]) is None)

print("== ADMIN: vehicles, listings, users, money")
r = submit(A, f"/admin/vehicles/{vid}", find_form(get(A, f"/admin/vehicles/{vid}"), has=["vehicleId", "to"]), {"to": "IN_SERVICE"}) if False else ""
done = sql("select b.id from bookings b where b.vehicle_id='%s' and b.status='ACTIVE' limit 1" % vid)
act = find_form(get(A, f"/admin/bookings/{done}"), has=["bookingId", "reason"])
submit(A, f"/admin/bookings/{done}", act, {}, button=("to", "COMPLETED"))
chg = find_form(get(A, f"/admin/vehicles/{vid}"), has=["vehicleId", "to"])
r = submit(A, f"/admin/vehicles/{vid}", chg, {"to": "IN_SERVICE"})
check("after the return the vehicle can go in service; upcoming bookings are reported, never cancelled", sql(f"select status from vehicles where id='{vid}'") == "IN_SERVICE" and "ok=status_IN_SERVICE" in r, r)
check("a vehicle in service can no longer be booked on its public page", "Temporarily unavailable" in text(get(None, f"/vehicles/{vid}")))
page = text(get(A, f"/admin/vehicles/{vid}"))
check("from service it can go back to available or be retired", "Available (leave the service)" in page and "Retired" in page)
r = submit(A, f"/admin/vehicles/{vid}", find_form(get(A, f"/admin/vehicles/{vid}"), has=["vehicleId", "to"]), {"to": "RETIRED"})
page = text(get(A, f"/admin/vehicles/{vid}"))
check("a retired vehicle can only be reactivated through service", sql(f"select status from vehicles where id='{vid}'") == "RETIRED" and "In service (reactivate)" in page and "Available (leave the service)" not in page, r)
check("a retired vehicle has no public page", status(None, f"/vehicles/{vid}").startswith("404"))
r = submit(A, f"/admin/vehicles/{vid}", find_form(get(A, f"/admin/vehicles/{vid}"), has=["vehicleId", "to"]), {"to": "AVAILABLE"})
check("forcing RETIRED -> AVAILABLE is refused by the server", sql(f"select status from vehicles where id='{vid}'") == "RETIRED" and "error=INVALID_TRANSITION" in r, r)
pend = sql("select id from vehicles where listing_status='PENDING' and plate not like 'UI-%' limit 1")
lst = get(A, "/admin/vehicles?listing=PENDING")
mod = find_form(lst, has=["vehicleId", "returnTo"], button=("decision", "approve"))
mid = [v for n, v, t in mod["fields"] if n == "vehicleId"][0]
r = submit(A, "/admin/vehicles", mod, button=("decision", "approve"))
check("a pending listing is approved and becomes public", sql(f"select listing_status from vehicles where id='{mid}'") == "APPROVED" and status(None, f"/vehicles/{mid}").startswith("200"), r)
# users
own_id = sql("select id from users where email='demo.owner@example.com'")
adm_id = sql(f"select id from users where email='{ADMIN_EMAIL}'")
uf = get(A, f"/admin/users?confirm={own_id}&to=CUSTOMER")
check("the role change asks for a confirmation that lists the rules", "Confirm the change" in text(uf) and "never cancelled automatically" in text(uf))
cf = find_form(uf, has=["userId", "role"])
r = submit(A, "/admin/users", cf)
check("demoting an owner who still has live vehicles is refused", "error=VEHICLES_NOT_RETIRED" in r and sql(f"select role from users where id='{own_id}'") == "OWNER", r)
r = submit(A, "/admin/users", cf, {"userId": adm_id, "role": "CUSTOMER"})
check("an administrator cannot change their own role", "error=SELF" in r and sql(f"select role from users where id='{adm_id}'") == "ADMIN", r)
cust2 = sql("select id from users where email='demo.customer2@example.com'")
r = submit(A, "/admin/users", cf, {"userId": cust2, "role": "OWNER"})
check("promotions are allowed", sql(f"select role from users where id='{cust2}'") == "OWNER" and "ok=1" in r, r)
check("a promoted user gets the new area immediately, without logging in again", status("/tmp/j_cust2", "/provider").startswith("200"))
# payouts and rates
pp = get(A, "/admin/payouts")
rate = find_form(pp, has=["ownerId", "percent"])
r = submit(A, "/admin/payouts", rate, {"percent": "3"})
check("a company rate below 5% is refused", "error=rate" in r and sql(f"select commission_bps from users where id='{co_id}'") == "800", r)
r = submit(A, "/admin/payouts", rate, {"percent": "7.5"})
check("a valid company rate is saved in basis points", sql(f"select commission_bps from users where id='{co_id}'") == "750", r)
newb = sql(f"select commission_bps from bookings b join vehicles v on v.id=b.vehicle_id where v.owner_id='{co_id}' order by b.created_at limit 1")
check("old bookings keep the rate they had", newb == "800", newb)
r = submit(A, "/admin/payouts", rate, {"ownerId": own_id, "percent": "9"})
check("the rate of an individual owner cannot be configured", "error=not_company" in r and sql(f"select commission_bps from users where id='{own_id}'") in ("", None), r)
po = find_form(pp, has=["ownerId", "amountRon"])
b0 = sql(f"select count(*) from payouts where owner_id='{own_id}'")
submit(A, "/admin/payouts", po, {"ownerId": own_id, "amountRon": "50", "note": "UI test payout"})
check("a payout is recorded", int(sql(f"select count(*) from payouts where owner_id='{own_id}'")) == int(b0) + 1)
