check("a payout to a plain customer is refused", "error=payout" in r, r)
# locations, csv
lf = find_form(get(A, "/admin/locations"), has=["name", "city", "county"])
submit(A, "/admin/locations", lf, {"name": "UI Test Base", "city": "Testville", "county": "Testcounty", "address": "Demo Street 99 (fictional address)", "phone": "+40 000 000 000", "hours": "Mon-Fri 09:00-17:00"})
check("a location is saved and offered in the catalog filters", sql("select count(*) from locations where name='UI Test Base'") == "1" and "UI Test Base" in text(get(None, "/vehicles")))
