check("the CSV is for administrators only", status("/tmp/j_own", "/admin/finance/export").startswith("307") or status(None, "/admin/finance/export").startswith("401"))
check("anonymous visitors get 401", status(None, "/admin/finance/export").startswith("401"))
check("the finance report page shows the totals", "Kept by the platform" in text(get(A, "/admin/finance")))
